
import os,base64,io,time,subprocess,sys
os.environ["HF_HOME"]="/kaggle/temp/hf"
subprocess.run([sys.executable,"-m","pip","install","-q","-U","diffusers","transformers","accelerate","sentencepiece","imageio","imageio-ffmpeg"],check=True)
import torch
from PIL import Image
from diffusers import LTXImageToVideoPipeline
from diffusers.utils import export_to_video
img=Image.open(io.BytesIO(base64.b64decode(""))).convert("RGB")
t0=time.time()
pipe=LTXImageToVideoPipeline.from_pretrained("Lightricks/LTX-Video",torch_dtype=torch.bfloat16)
pipe.enable_model_cpu_offload(); pipe.vae.enable_tiling()
print("loaded",time.time()-t0,flush=True)
prompt=("A cute young girl in a pink headscarf sighs deeply, her shoulders rise and fall, she lowers her head slightly then lifts it back up and turns her head a little to the left, then back to the camera. "
"She blinks twice, her eyebrows rise in worry and her eyes glisten with sadness. Clearly visible natural head and body movement, gentle handheld cinematic feel, mouth closed, 3D animated film, warm golden light")
neg="worst quality, inconsistent motion, blurry, jittery, distorted, morphing face, changing identity, text, watermark"
t1=time.time()
out=pipe(image=img,prompt=prompt,negative_prompt=neg,width=480,height=832,num_frames=73,num_inference_steps=30,guidance_scale=5.0,generator=torch.Generator().manual_seed(11)).frames[0]
print("generated",time.time()-t1,flush=True)
export_to_video(out,"/kaggle/working/ltx_test2.mp4",fps=24)
print("done")
